from dataclasses import dataclass, field
from enum import Enum


class Priority(Enum):
    HIGH = 1
    NORMAL = 2
    LOW = 3


@dataclass
class Task:
    title: str
    priority: Priority = Priority.NORMAL
    tags: list = field(default_factory=list)
    done: bool = False


def parse_task(text):
    words, tags, priority = [], [], Priority.NORMAL
    for word in text.split():
        if word.startswith("#") and len(word) > 1:
            tag = word[1:].lower()
            if tag not in tags:
                tags.append(tag)
        elif word.startswith("!"):
            name = word[1:].upper()
            if name not in Priority.__members__:
                raise ValueError(f"unknown priority: {word}")
            priority = Priority[name]
        else:
            words.append(word)
    return Task(" ".join(words), priority, tags)


def sort_tasks(tasks):
    return sorted(tasks, key=lambda t: (t.done, t.priority.value, t.title))


def with_tag(tasks, tag):
    tag = tag.lower().lstrip("#")
    found = []
    for t in tasks:
        if tag in t.tags:
            found.append(t)
    return found

unitTests:
@test("parsing")
def _():
    check_eq(parse_task("Write report !high #work #urgent"), Task("Write report", Priority.HIGH, ["work", "urgent"]))
    check_eq(parse_task("  buy   milk "), Task("buy milk"))
    check_eq(parse_task("#Home call mum !LOW #home"), Task("call mum", Priority.LOW, ["home"]))
    check_raises(ValueError, parse_task, "x !someday")

@test("each task has its own tags")
def _():
    a, b = Task("a"), Task("b")
    a.tags.append("x")
    check_eq(b.tags, [])

@test("sorting")
def _():
    tasks = [Task("b", Priority.LOW), Task("a", Priority.LOW), Task("z", Priority.HIGH, done=True), Task("m", Priority.HIGH)]
    check_eq([t.title for t in sort_tasks(tasks)], ["m", "a", "b", "z"])
    check_eq(tasks[0].title, "b")

@test("tags")
def _():
    tasks = [parse_task("x #Work"), parse_task("y #home"), parse_task("z #work #home")]
    check_eq([t.title for t in with_tag(tasks, "WORK")], ["x", "z"])
    check_eq([t.title for t in with_tag(tasks, "#home")], ["y", "z"])

